// Compiled from a Google Scholar literature search on sign language research
// and datasets across Africa (search restricted to African countries/regions).
export const PUBLICATIONS: Publication[] = [{"id": 1, "title": "AI4KSL: Kenyan Sign Language Dataset for Bridging Communication Barriers Among Deaf Learners", "authors": "Wanzare, L.D.A., Okutoyi, J., Kang'ahi, M., Ayere, M.", "year": 2024, "venue": "arXiv preprint 2410.18295", "country": "Kenya", "link": "https://scholar.google.com/scholar?q=AI4KSL%3A+Kenyan+Sign+Language+Dataset+for+Bridging+Communication+Barriers+Among+Deaf+Learners", "summary": "Describes the AI4KSL project, which built an open-access dataset of spontaneous and elicited Kenyan Sign Language from 48 teachers and 400 Deaf learners to support English-to-KSL translation technology.", "region": "East Africa"}, {"id": 2, "title": "Kenyan Sign Language Word-Based Pose Dataset", "authors": "Maina, E., Wanzare, L., Obuhuma, J., Ayere, M., Kang'ahi, M., Okutoyi, J.", "year": 2025, "venue": "Data in Brief, DOI:10.1016/j.dib.2025.111502", "country": "Kenya", "link": "https://scholar.google.com/scholar?q=Kenyan+Sign+Language+Word-Based+Pose+Dataset", "summary": "Presents 20,000 KSL gesture recordings converted to anonymised pose-estimation stickman data using MediaPipe, intended for machine learning research on a low-resource sign language.", "region": "East Africa"}, {"id": 3, "title": "AfriSign: African Sign Languages Machine Translation", "authors": "Takyi, K., Gyening, R., Gueuwou, S., Nyarko, M., Adade, R., Borkor, R., Boadu-Acheampong, S., Tabari, L.", "year": 2025, "venue": "Discover Artificial Intelligence, DOI:10.1007/s44163-025-00227-7", "country": "Multi-country (Ghana, Nigeria, Kenya, Zambia, Zimbabwe, South Africa)", "link": "https://scholar.google.com/scholar?q=AfriSign%3A+African+Sign+Languages+Machine+Translation", "summary": "Introduces the first multilingual African sign language translation dataset spanning six countries, built from Bible-verse videos, and reports a transformer translation model reaching over 94 percent accuracy.", "region": "Pan-African"}, {"id": 4, "title": "A Large-Scale Multimodal Dataset for Healthcare-Domain Ghanaian Sign Language Translation and Retrieval-Based Synthesis (SignTalk-Gh)", "authors": "Ahene, E., Frowne, C., Adetor, R., Amoah, N., Adade, R., Owusu-Agyemang, K., Gyening, R., Agyemang, J., Kponyo, B., Acheampong, E., Kponyo, J.", "year": 2026, "venue": "Scientific Reports, DOI:10.1038/s41598-026-43478-9", "country": "Ghana", "link": "https://scholar.google.com/scholar?q=A+Large-Scale+Multimodal+Dataset+for+Healthcare-Domain+Ghanaian+Sign+Language+Translation+and+Retrieval-Based+Synthesis+%28SignTalk-Gh%29", "summary": "Introduces the first domain-specific Ghanaian Sign Language dataset for healthcare, built from doctor-patient conversations to support recognition and retrieval-based translation in clinical settings.", "region": "West Africa"}, {"id": 5, "title": "Ghanaian Sign Language Recognition Using Deep Learning", "authors": "Edward, M., et al.", "year": 2019, "venue": "Proc. Intl Conf. on Pattern Recognition and Artificial Intelligence, DOI:10.1145/3357777.3357784", "country": "Ghana", "link": "https://scholar.google.com/scholar?q=Ghanaian+Sign+Language+Recognition+Using+Deep+Learning", "summary": "Builds an original Ghanaian Sign Language dataset in the absence of a public one and evaluates a convolutional neural network for recognition, with plans to release the dataset for future research.", "region": "West Africa"}, {"id": 6, "title": "Sign-to-Speech Model for Sign Language Understanding: A Case Study of Nigerian Sign Language", "authors": "Kolawole, S., Osakuade, O., Saxena, N., Olorisade, B.K.", "year": 2021, "venue": "arXiv preprint 2111.00995", "country": "Nigeria", "link": "https://scholar.google.com/scholar?q=Sign-to-Speech+Model+for+Sign+Language+Understanding%3A+A+Case+Study+of+Nigerian+Sign+Language", "summary": "Presents a pioneering Nigerian Sign Language dataset of 5,000 images across 137 signs collected from Deaf communities, benchmarking object-detection and classification models for sign-to-speech conversion.", "region": "West Africa"}, {"id": 7, "title": "Development of a Computer-Aided Real-Time Interpretation System for Indigenous Sign Language in Nigeria Using CNN", "authors": "Olabanji, A.O., Ponnle, A.A.", "year": 2022, "venue": "Journal article (as cited in Scientific Reports 2026)", "country": "Nigeria", "link": "https://scholar.google.com/scholar?q=Development+of+a+Computer-Aided+Real-Time+Interpretation+System+for+Indigenous+Sign+Language+in+Nigeria+Using+CNN", "summary": "Proposes a Nigerian Sign Language dataset of 15,000 images across 15 indigenous signs and trains a four-layer CNN, reporting accuracy above 95 percent on training and validation data.", "region": "West Africa"}, {"id": 8, "title": "A Deep Learning Framework for Ethiopian Sign Language Recognition Using Skeleton-Based Representation", "authors": "(Authors per Scientific Reports)", "year": 2025, "venue": "Scientific Reports, DOI:10.1038/s41598-025-19937-0", "country": "Ethiopia", "link": "https://scholar.google.com/scholar?q=A+Deep+Learning+Framework+for+Ethiopian+Sign+Language+Recognition+Using+Skeleton-Based+Representation", "summary": "Builds a 5,600-video skeleton-keypoint dataset via MediaPipe Holistic and benchmarks CNN-LSTM, LSTM, BiLSTM and GRU architectures, reporting 94 percent accuracy in signer-dependent settings and 73 percent signer-independent.", "region": "East Africa"}, {"id": 9, "title": "Ethiopian Sign Language Recognition Using Deep Convolutional Neural Network", "authors": "Abeje, B.T., Salau, A.O., Mengistu, A.D., Tamiru, N.K.", "year": 2022, "venue": "Multimedia Tools and Applications, DOI:10.1007/s11042-022-12768-5", "country": "Ethiopia", "link": "https://scholar.google.com/scholar?q=Ethiopian+Sign+Language+Recognition+Using+Deep+Convolutional+Neural+Network", "summary": "Develops a CNN-based system translating Ethiopian Sign Language to Amharic alphabet characters using images collected from hearing-impaired students, reporting high training and validation accuracy.", "region": "East Africa"}, {"id": 10, "title": "Word Level Ethiopian Sign Language Recognition Using Hybrid CNN-LSTM Model", "authors": "(Multiple authors, Addis Ababa University research)", "year": 2025, "venue": "Conference/preprint (ResearchGate)", "country": "Ethiopia", "link": "https://scholar.google.com/scholar?q=Word+Level+Ethiopian+Sign+Language+Recognition+Using+Hybrid+CNN-LSTM+Model", "summary": "Applies a hybrid CNN-LSTM architecture to word-level Ethiopian Sign Language recognition, combining single-frame feature extraction with sequence modelling across signed video.", "region": "East Africa"}, {"id": 11, "title": "A Comparative Study on Performance of SVM and CNN in Tanzania Sign Language Translation Using Image Recognition", "authors": "Myagila, K., Kilavo, H.", "year": 2021, "venue": "Applied Artificial Intelligence, DOI:10.1080/08839514.2021.2005297", "country": "Tanzania", "link": "https://scholar.google.com/scholar?q=A+Comparative+Study+on+Performance+of+SVM+and+CNN+in+Tanzania+Sign+Language+Translation+Using+Image+Recognition", "summary": "Compares SVM and CNN models on an image dataset of Tanzanian Sign Language signs, finding CNN outperforms SVM and establishing an early benchmark for Tanzanian sign recognition research.", "region": "East Africa"}, {"id": 12, "title": "Efficient Spatio-Temporal Modeling for Sign Language Recognition Using CNN and RNN Architectures", "authors": "Myagila, K., Nyambo, D.G., Dida, M.A.", "year": 2025, "venue": "Frontiers in Artificial Intelligence, DOI:10.3389/frai.2025.1630743", "country": "Tanzania", "link": "https://scholar.google.com/scholar?q=Efficient+Spatio-Temporal+Modeling+for+Sign+Language+Recognition+Using+CNN+and+RNN+Architectures", "summary": "Uses Tanzanian Sign Language videos captured on mobile phones to compare CNN-LSTM and CNN-GRU architectures, examining the effect of hand dominance and signer independence on recognition accuracy.", "region": "East Africa"}, {"id": 13, "title": "CASL-W60: A Word-Level Dataset for Central African Sign Language Recognition", "authors": "(Multiple authors)", "year": 2025, "venue": "Data in Brief / ScienceDirect", "country": "Central Africa", "link": "https://scholar.google.com/scholar?q=CASL-W60%3A+A+Word-Level+Dataset+for+Central+African+Sign+Language+Recognition", "summary": "Introduces a 60-word Central African Sign Language dataset collected from 19 volunteers, addressing the near-total absence of regional word-level datasets for the area's sign languages.", "region": "Central Africa"}, {"id": 14, "title": "South African Sign Language Dataset Development and Translation: A Glove-Based Approach", "authors": "McInnes, B.", "year": 2014, "venue": "University of Cape Town (Semantic Scholar)", "country": "South Africa", "link": "https://scholar.google.com/scholar?q=South+African+Sign+Language+Dataset+Development+and+Translation%3A+A+Glove-Based+Approach", "summary": "Describes an early glove-based sensor dataset capturing static South African Sign Language gestures, forming a foundation for later SASL recognition research at UCT.", "region": "Southern Africa"}, {"id": 15, "title": "The South African Sign Language Machine Translation Project: Issues on Non-Manual Sign Generation", "authors": "(UWC SASL-MT research group)", "year": 2003, "venue": "AFRIGRAPH '03, DOI:10.1145/602330.602339", "country": "South Africa", "link": "https://scholar.google.com/scholar?q=The+South+African+Sign+Language+Machine+Translation+Project%3A+Issues+on+Non-Manual+Sign+Generation", "summary": "Reports on an English-to-SASL machine translation system driven by a signing avatar, extending a syntax-based parser to generate non-manual signing features such as facial expression and stress patterns.", "region": "Southern Africa"}, {"id": 16, "title": "Investigating Signer-Independent Sign Language Recognition on the LSA64 Dataset", "authors": "Marais, M., Brown, D., Connan, J., Boby, A., Kuhlane, L.L.", "year": 2022, "venue": "Southern Africa Telecommunication Networks and Applications Conference (SATNAC)", "country": "South Africa", "link": "https://scholar.google.com/scholar?q=Investigating+Signer-Independent+Sign+Language+Recognition+on+the+LSA64+Dataset", "summary": "Examines signer-independent recognition performance for sign language models, contributing to the broader South African research programme on automated sign recognition.", "region": "Southern Africa"}, {"id": 17, "title": "Upper Body Pose Recognition and Estimation Towards the Translation of South African Sign Language", "authors": "Achmed, I.", "year": 2011, "venue": "Doctoral dissertation, University of the Western Cape", "country": "South Africa", "link": "https://scholar.google.com/scholar?q=Upper+Body+Pose+Recognition+and+Estimation+Towards+the+Translation+of+South+African+Sign+Language", "summary": "A doctoral study on estimating upper-body pose as a step toward automated South African Sign Language translation, cited widely in later African sign-language machine-translation research.", "region": "Southern Africa"}, {"id": 18, "title": "Alabib-65: A Realistic Dataset for Algerian Sign Language Recognition", "authors": "Khellas, K., Seghir, R.", "year": 2023, "venue": "ACM Transactions on Asian and Low-Resource Language Information Processing", "country": "Algeria", "link": "https://scholar.google.com/scholar?q=Alabib-65%3A+A+Realistic+Dataset+for+Algerian+Sign+Language+Recognition", "summary": "Contributes a realistic North African sign language dataset for Algerian Sign Language, used as a comparison point in subsequent African sign-language dataset papers.", "region": "North Africa"}, {"id": 19, "title": "Automatic Speech Recognition (ASR) for African Low-Resource Languages: A Systematic Literature Review", "authors": "(Multiple authors)", "year": 2025, "venue": "arXiv preprint 2510.01145", "country": "Pan-African", "link": "https://scholar.google.com/scholar?q=Automatic+Speech+Recognition+%28ASR%29+for+African+Low-Resource+Languages%3A+A+Systematic+Literature+Review", "summary": "A PRISMA-guided review of 71 studies on speech and language technology for African low-resource languages, providing useful context on datasets, models and evaluation gaps relevant to sign language work.", "region": "Pan-African"}, {"id": 20, "title": "Mendeley EthSL Alphabet Dataset: RGB Images for Static Ethiopian Sign Language Gesture Recognition", "authors": "Abeje, B.T., et al.", "year": 2022, "venue": "Mendeley Data", "country": "Ethiopia", "link": "https://scholar.google.com/scholar?q=Mendeley+EthSL+Alphabet+Dataset%3A+RGB+Images+for+Static+Ethiopian+Sign+Language+Gesture+Recognition", "summary": "Provides a public collection of 1,172 RGB images of Ethiopian Sign Language alphabet gestures for static recognition and landmark-extraction research.", "region": "East Africa"}];
